 const p0=[CX+34*Math.cos(-118*D),CY+34*Math.sin(-118*D)],p1=[CX+82*Math.cos(-118*D),CY+82*Math.sin(-118*D)];
 g("path",{d:"M"+p0.map(v=>v.toFixed(1)).join(" ")+"L"+p1.map(v=>v.toFixed(1)).join(" ")+"L"+(p1[0]-44)+" "+p1[1],class:"lead"},grp);
 txt(grp,"SOL — ARBOR MAGNA",p1[0]-48,p1[1]+3,{"text-anchor":"end",class:"lbl"});
})();

